pm.test("Ответ должен содержать код статуса 200 и данные в формате json-массив", function () {
    pm.response.to.be.ok;
    pm.response.to.be.json;
    const body = pm.response.json();
    pm.expect(body).to.be.an('array');
});

const source = pm.collectionVariables.get('response');
const target = pm.response.json();

let found;
target.forEach(function (element) {
    if (element.id == source.id) {
        found = element;
    }
});

pm.test("Комментарий должен быть найден в списке", function () {
    pm.expect(found, 'Комментарий с id=' + source.id + ' не найден в ответе').to.not.be.undefined;
});

pm.test("Комментарий должен содержать поля: id, text, author, event, createdOn, updatedOn", function () {
    pm.expect(found).to.have.property('id');
    pm.expect(found).to.have.property('text');
    pm.expect(found).to.have.property('author');
    pm.expect(found).to.have.property('event');
    pm.expect(found).to.have.property('createdOn');
    pm.expect(found).to.have.property('updatedOn');
});

pm.test("Данные в ответе должны соответствовать данным в запросе", function () {
    pm.expect(found.id).to.not.be.null;
    pm.expect(found.text).equal(source.text, 'Текст комментария должен соответствовать тексту комментария в запросе');
});

const main = async () => {
    const api = new API(pm);
    const rnd = new RandomUtils();

    try {
        const initiator = await api.addUser(rnd.getUser());
        const category = await api.addCategory(rnd.getCategory());
        let event = await api.addEvent(initiator.id, rnd.getEvent(category.id));
        event = await api.publishEvent(event.id);

        const participant = await api.addUser(rnd.getUser());
        const request = await api.addParticipationRequest(participant.id, event.id);
        if (request.status === 'PENDING') {
            await api.confirmParticipationRequest(initiator.id, event.id, request.id);
        }

        const comment = await api.addComment(participant.id, event.id, rnd.getComment());

        pm.collectionVariables.set('userId', participant.id);
        pm.collectionVariables.set('eventId', event.id);
        pm.collectionVariables.set("response", comment);
    } catch (err) {
        console.error("Ошибка при подготовке тестовых данных.", err);
    }

};

const interval = setInterval(() => { }, 1000);

setTimeout(async () => {
    try {
        await main();
    } catch (e) {
        console.error(e);
    } finally {
        clearInterval(interval);
    }
},
    100
);

