pm.test("Ответ должен содержать код статуса 200 и данные в формате json-массив", function () {
    pm.response.to.be.ok;
    pm.response.to.be.withBody;
    pm.response.to.be.json;
    pm.expect(pm.response.json()).to.be.an('array');
});

const target = pm.response.json();
const totalComments = Number(pm.collectionVariables.get('totalComments'));
const outOfRangeFrom = Number(pm.collectionVariables.get('outOfRangeFrom'));

pm.test("Подготовка: from за пределами количества", function () {
    pm.expect(totalComments).to.be.greaterThan(0);
    pm.expect(outOfRangeFrom).to.be.greaterThan(totalComments);
});

pm.test("from за пределами → пустой массив (не 400/404)", function () {
    pm.expect(target).to.be.an('array').that.is.empty;
    pm.expect(target.length).to.eql(0);
});

const main = async () => {
    const api = new API(pm);
    const rnd = new RandomUtils();

    try {
        const initiator = await api.addUser(rnd.getUser());
        const category = await api.addCategory(rnd.getCategory());
        let event = await api.addEvent(initiator.id, rnd.getEvent(category.id));
        event = await api.publishEvent(event.id);

        const participant = await api.addUser(rnd.getUser());
        const request = await api.addParticipationRequest(participant.id, event.id);
        if (request.status === 'PENDING') {
            await api.confirmParticipationRequest(initiator.id, event.id, request.id);
        }

        const TOTAL_COMMENTS = Number(pm.collectionVariables.get('totalComments'));
        if (!TOTAL_COMMENTS || TOTAL_COMMENTS <= 0) {
            throw new Error('totalComments должен быть > 0, сейчас: ' + TOTAL_COMMENTS);
        }

        for (let i = 0; i < TOTAL_COMMENTS; i++) {
            await api.addComment(participant.id, event.id, rnd.getComment());
        }

        pm.collectionVariables.set('eventId', event.id);
        pm.collectionVariables.set('outOfRangeFrom', TOTAL_COMMENTS + 10);
    } catch (err) {
        console.error("Ошибка при подготовке тестовых данных.", err);
    }
};

