const target = pm.response.json();
const totalComments = Number(pm.collectionVariables.get('totalComments'));
const bigSize = Number(pm.collectionVariables.get('bigSize'));

pm.test("Подготовка: size больше количества", function () {
    pm.expect(totalComments).to.be.greaterThan(0);
    pm.expect(bigSize).to.be.greaterThan(totalComments);
});

pm.test("size больше количества → вернулись все элементы", function () {
    pm.expect(target.length).to.eql(totalComments);
});

pm.test("size больше количества → length < size (не обрезано до size)", function () {
    pm.expect(target.length).to.be.lessThan(bigSize);
});

