const target = pm.response.json();
const totalComments = Number(pm.collectionVariables.get('totalComments'));
const lastPageFrom = Number(pm.collectionVariables.get('lastPageFrom'));
const lastPageSize = Number(pm.collectionVariables.get('lastPageSize'));
const expectedRemainder = Number(pm.collectionVariables.get('expectedRemainder'));

pm.test("Подготовка: from=10, size=10, остаток=5", function () {
    pm.expect(totalComments).to.be.greaterThan(5);
    pm.expect(lastPageFrom).to.eql(totalComments - expectedRemainder);
    pm.expect(lastPageSize).to.be.greaterThan(expectedRemainder);
});

pm.test("Последняя страница содержит ровно остаток (5)", function () {
    pm.expect(target.length).to.eql(expectedRemainder);
});

pm.test("Остаток меньше size (последняя страница, не полная)", function () {
    pm.expect(target.length).to.be.lessThan(lastPageSize);
});

pm.test("Остаток не пуст (страница не за пределами)", function () {
    pm.expect(target.length).to.be.greaterThan(0);
});

const main = async () => {
    const api = new API(pm);
    const rnd = new RandomUtils();

    try {
        const initiator = await api.addUser(rnd.getUser());
        const category = await api.addCategory(rnd.getCategory());
        let event = await api.addEvent(initiator.id, rnd.getEvent(category.id));
        event = await api.publishEvent(event.id);

        const participant = await api.addUser(rnd.getUser());
        const request = await api.addParticipationRequest(participant.id, event.id);
        if (request.status === 'PENDING') {
